<?php
session_start(); require_once __DIR__.'/../autenticacao.php'; require_once __DIR__.'/../gerente/conexaoDB.php'; require_once __DIR__.'/../cabecalho.php'; require_once __DIR__.'/../includes/auditoria.php'; exigirLogin('balconista');
$farmaciaId=(int)$_SESSION['farmacia_id']; $id=(int)($_GET['id']??$_POST['id']??0);
$stmt=mysqli_prepare($conexao,'SELECT * FROM clientes WHERE id=? AND farmacia_id=?'); mysqli_stmt_bind_param($stmt,'ii',$id,$farmaciaId); mysqli_stmt_execute($stmt); $cliente=mysqli_fetch_assoc(mysqli_stmt_get_result($stmt)); if(!$cliente){ header('Location: clientes.php'); exit; }
$erro='';
if($_SERVER['REQUEST_METHOD']==='POST'){ $nome=trim($_POST['nome']??''); $cpf=preg_replace('/\D/','',$_POST['cpf']??''); $telefone=trim($_POST['telefone']??''); $email=trim($_POST['email']??''); if($nome===''||($cpf!==''&&strlen($cpf)!==11)||($email!==''&&!filter_var($email,FILTER_VALIDATE_EMAIL))){$erro='Verifique nome, CPF e e-mail.';}else{ $cpfBanco=$cpf===''?null:$cpf; $stmt=mysqli_prepare($conexao,'UPDATE clientes SET nome=?,cpf=?,telefone=?,email=? WHERE id=? AND farmacia_id=?'); mysqli_stmt_bind_param($stmt,'ssssii',$nome,$cpfBanco,$telefone,$email,$id,$farmaciaId); if(mysqli_stmt_execute($stmt)){ registrarAuditoria($conexao,'editar','cliente',$id,'Cadastro do cliente atualizado'); header('Location: clientes.php?editado=1'); exit;} $erro='Não foi possível atualizar. Verifique se o CPF já pertence a outro cliente.'; }}
?>
<!DOCTYPE html><html lang="pt-BR"><head><?php recursosCabeca('Editar cliente'); ?></head><body><?php cabecalho('Sistema de Gestão','balconista','clientes'); ?><main class="container py-4"><section class="card shadow-sm rounded-4 p-4 mx-auto" style="max-width:800px"><h2 class="h4 fw-bold">EDITAR CLIENTE</h2><?php if($erro){ ?><div class="alert alert-danger"><?php echo htmlspecialchars($erro); ?></div><?php } ?><form method="POST" class="row g-3"><input type="hidden" name="id" value="<?php echo $id; ?>"><div class="col-md-6"><label class="form-label">Nome</label><input class="form-control" name="nome" value="<?php echo htmlspecialchars($cliente['nome']); ?>" required></div><div class="col-md-6"><label class="form-label">CPF</label><input class="form-control" name="cpf" value="<?php echo htmlspecialchars($cliente['cpf']??''); ?>"></div><div class="col-md-6"><label class="form-label">Telefone</label><input class="form-control" name="telefone" value="<?php echo htmlspecialchars($cliente['telefone']??''); ?>"></div><div class="col-md-6"><label class="form-label">E-mail</label><input class="form-control" type="email" name="email" value="<?php echo htmlspecialchars($cliente['email']??''); ?>"></div><div class="col-12 d-flex gap-2"><a class="btn btn-secondary rounded-pill" href="clientes.php">VOLTAR</a><button class="btn btn-primary rounded-pill">SALVAR</button></div></form></section></main><?php recursosRodape(); ?></body></html>